import { NextRequest, NextResponse } from 'next/server';
import { getDb } from '@/lib/db';
import { getSessionId } from '@/lib/session';

export async function POST(request: NextRequest) {
  const db = getDb(getSessionId(request));
  const { filter } = await request.json();
  if (!['all', 'active', 'completed'].includes(filter)) {
    return NextResponse.json({ error: 'filter must be all|active|completed' }, { status: 400 });
  }
  db.prepare("INSERT OR REPLACE INTO gym_state(key, value) VALUES ('filter', ?)").run(filter);
  return NextResponse.json({ filter });
}

import { NextRequest, NextResponse } from 'next/server';
import { getDb } from '@/lib/db';
import { getSessionId } from '@/lib/session';
import { randomUUID } from 'crypto';

export async function GET(request: NextRequest) {
  const db = getDb(getSessionId(request));
  const filter = request.nextUrl.searchParams.get('filter') ?? 'all';
  let rows;
  if (filter === 'active') {
    rows = db.prepare('SELECT * FROM items WHERE done = 0 ORDER BY created_at').all();
  } else if (filter === 'completed') {
    rows = db.prepare('SELECT * FROM items WHERE done = 1 ORDER BY created_at').all();
  } else {
    rows = db.prepare('SELECT * FROM items ORDER BY created_at').all();
  }
  const state = db.prepare("SELECT value FROM gym_state WHERE key = 'filter'").get() as any;
  return NextResponse.json({ items: rows, filter: state?.value ?? 'all' });
}

export async function POST(request: NextRequest) {
  const db = getDb(getSessionId(request));
  const { text } = await request.json();
  if (!text?.trim()) return NextResponse.json({ error: 'text required' }, { status: 400 });
  const id = 'itm_' + randomUUID().slice(0, 8);
  db.prepare('INSERT INTO items(id, text, done) VALUES (?, ?, 0)').run(id, text.trim());
  return NextResponse.json(db.prepare('SELECT * FROM items WHERE id = ?').get(id));
}

