import { NextRequest, NextResponse } from 'next/server';
import { getDb, getCurrentTask } from '@/lib/db';
import { getSessionId } from '@/lib/session';
import { forwardEvent } from '@/lib/eval-server';
import path from 'path';

async function runEval(sessionId: string, agentAnswer?: unknown) {
  const task = getCurrentTask(sessionId);
  if (!task) return null;

  const evalPath = 'file:///' + path.join(process.cwd(), 'eval.mjs').replace(/\\/g, '/');
  const load = new Function('p', 'return import(p)') as (p: string) => Promise<any>;
  const mod = await load(evalPath);
  const evalFns = mod.default ?? mod;
  const db = getDb(sessionId);

  const steps = agentAnswer !== undefined
    ? task.steps.map((s: any) =>
        s.evalFunc === 'check_retrieval'
          ? { ...s, metadata: { ...s.metadata, agentAnswer } }
          : s
      )
    : task.steps;

  const result = evalFns.compose_steps(db, { steps });
  return {
    success: result.success ?? false,
    reward: result.reward ?? 0,
    message: result.message ?? '',
    subResults: (result.subResults ?? []).map((s: any, i: number) => ({
      ...s, overrides: task.steps[i]?.overrides,
    })),
  };
}

export async function GET(request: NextRequest) {
  const sid = getSessionId(request);
  const task = getCurrentTask(sid);
  if (!task) return NextResponse.json({ error: 'No task started' }, { status: 400 });
  try {
    const result = await runEval(sid);
    forwardEvent('evaluate', { taskId: task.id, type: task.type, ...result });
    return NextResponse.json(result);
  } catch (e: any) {
    return NextResponse.json({ success: false, reward: 0, message: `Eval error: ${e.message}` }, { status: 500 });
  }
}

export async function POST(request: NextRequest) {
  const sid = getSessionId(request);
  const task = getCurrentTask(sid);
  if (!task) return NextResponse.json({ error: 'No task started' }, { status: 400 });
  try {
    const { agentAnswer } = await request.json();
    const result = await runEval(sid, agentAnswer);
    forwardEvent('evaluate', { taskId: task.id, type: task.type, agentAnswer, ...result });
    return NextResponse.json(result);
  } catch (e: any) {
    return NextResponse.json({ success: false, reward: 0, message: `Eval error: ${e.message}` }, { status: 500 });
  }
}

