import { NextRequest, NextResponse } from 'next/server';
import { getDb } from '@/lib/db';
import { getSessionId } from '@/lib/session';

export async function PATCH(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  const { id } = await params;
  const db = getDb(getSessionId(request));
  const body = await request.json();
  if (body.text !== undefined) {
    db.prepare('UPDATE items SET text = ? WHERE id = ?').run(body.text, id);
  }
  if (body.done !== undefined) {
    db.prepare('UPDATE items SET done = ? WHERE id = ?').run(body.done ? 1 : 0, id);
  }
  return NextResponse.json(db.prepare('SELECT * FROM items WHERE id = ?').get(id));
}

export async function DELETE(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  const { id } = await params;
  const db = getDb(getSessionId(request));
  db.prepare('DELETE FROM items WHERE id = ?').run(id);
  return NextResponse.json({ success: true });
}

import { NextRequest, NextResponse } from 'next/server';
import { createSession, destroySession } from '@/lib/db';
import { getSessionId } from '@/lib/session';

export async function POST() {
