}

export async function DELETE(request: NextRequest) {
  const sid = getSessionId(request);
  if (sid === 'default') return NextResponse.json({ error: 'Cannot destroy default session' }, { status: 400 });
  destroySession(sid);
  return NextResponse.json({ success: true });
}

import { NextRequest, NextResponse } from 'next/server';
import { startTask, getCurrentTask, loadAllTasks } from '@/lib/db';
import { getSessionId } from '@/lib/session';
import { forwardEvent } from '@/lib/eval-server';
import fs from 'fs';
import path from 'path';

export async function POST(
  request: NextRequest,
  { params }: { params: Promise<{ taskId: string }> }
) {
  const { taskId } = await params;
  const tasks = loadAllTasks();
  const task = tasks.find((t: any) => t.id === taskId);

  if (!task) {
    return NextResponse.json({ error: `Task "${taskId}" not found` }, { status: 404 });
  }

  const sharedSeed = path.join('tasks', '_shared', 'seed.sql');
  let seedPath: string;
  let extraSeedPath: string | undefined;

  if (task.type === 'advanced') {
    seedPath = sharedSeed;
    const perTask = path.join('tasks', 'advanced', taskId, 'seed.sql');
    if (fs.existsSync(path.join(process.cwd(), perTask))) extraSeedPath = perTask;
  } else {
    const perTask = path.join('tasks', 'primitives', taskId, 'seed.sql');
    seedPath = fs.existsSync(path.join(process.cwd(), perTask)) ? perTask : sharedSeed;
  }

  const sid = getSessionId(request);
  startTask(sid, seedPath, task, extraSeedPath);
  const current = getCurrentTask(sid)!;

  forwardEvent('start', { taskId, type: current.type, prompt: current.prompt });

  return NextResponse.json({ success: true, prompt: current.prompt, task: current });
}

