'use client';

import { useState, useEffect, useRef, useCallback } from 'react';

interface Item {
  id: string;
  text: string;
  done: number;
}

type Filter = 'all' | 'active' | 'completed';

export default function TodoApp() {
  const [items, setItems] = useState<Item[]>([]);
  const [filter, setFilter] = useState<Filter>('all');
  const [newText, setNewText] = useState('');
  const [editId, setEditId] = useState<string | null>(null);
  const [editText, setEditText] = useState('');
  const [gymOpen, setGymOpen] = useState(false);
  const [tasks, setTasks] = useState<any[]>([]);
  const [selectedTask, setSelectedTask] = useState('');
  const [prompt, setPrompt] = useState('');
  const [evalResult, setEvalResult] = useState<any>(null);
  const [agentAnswer, setAgentAnswer] = useState('');
  const fabRef = useRef<HTMLButtonElement>(null);

  const load = useCallback(async () => {
    const r = await fetch(`/api/items?filter=${filter}`);
    const d = await r.json();
    setItems(d.items);
    setFilter(d.filter);
  }, [filter]);

  useEffect(() => { load(); }, [filter]);

  useEffect(() => {
    fetch('/api/gym/tasks').then((r) => r.json()).then(setTasks);
  }, []);

  // Keyboard shortcut
  useEffect(() => {
    const handler = (e: KeyboardEvent) => {
      if (e.key === 'ArrowUp') setGymOpen((v) => !v);
    };
    window.addEventListener('keydown', handler);
    return () => window.removeEventListener('keydown', handler);
  }, []);

  async function addItem(e: React.FormEvent) {
    e.preventDefault();
    if (!newText.trim()) return;
    await fetch('/api/items', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ text: newText }) });
    setNewText('');
    load();
  }

  async function toggle(item: Item) {
    await fetch(`/api/items/${item.id}`, { method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ done: !item.done }) });
    load();
  }

  async function deleteItem(id: string) {
    await fetch(`/api/items/${id}`, { method: 'DELETE' });
    load();
  }

  async function saveEdit(id: string) {
    await fetch(`/api/items/${id}`, { method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ text: editText }) });
    setEditId(null);
    load();
  }

  async function changeFilter(f: Filter) {
    await fetch('/api/filter', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ filter: f }) });
    setFilter(f);
  }

  async function clearCompleted() {
    await fetch('/api/clear-completed', { method: 'POST' });
    load();
  }

  // Gym controls
  async function startTask() {
    if (!selectedTask) return;
    const r = await fetch(`/api/gym/start/${selectedTask}`, { method: 'POST' });
    const d = await r.json();
    setPrompt(d.prompt ?? '');
    setEvalResult(null);
    setAgentAnswer('');
    load();
  }

  async function evaluate() {
    const body = agentAnswer ? JSON.stringify({ agentAnswer }) : undefined;
    const r = await fetch('/api/gym/evaluate', {
      method: agentAnswer ? 'POST' : 'GET',
      headers: body ? { 'Content-Type': 'application/json' } : {},
      body,
    });
    setEvalResult(await r.json());
  }

  async function reset() {
    await fetch('/api/gym/reset', { method: 'POST' });
    setPrompt('');
    setEvalResult(null);
    load();
  }

  const activeCount = items.filter((i) => !i.done).length;
  const hasCompleted = items.some((i) => i.done);

  const selectedTaskMeta = tasks.find((t) => t.id === selectedTask);
  const isRetrieval = selectedTaskMeta?.evalFunc === 'check_retrieval' || selectedTaskMeta?.json_schema;

  return (
    <div className="max-w-lg mx-auto px-4 py-8">
      {/* Header */}
      <h1 className="text-3xl font-bold text-indigo-600 mb-6 tracking-tight">Todo</h1>

      {/* Add form */}
      <form onSubmit={addItem} className="flex gap-2 mb-6">
        <input
          value={newText}
          onChange={(e) => setNewText(e.target.value)}
          placeholder="What needs to be done?"
          className="flex-1 rounded-xl border border-gray-200 px-4 py-3 text-sm shadow-sm focus:outline-none focus:ring-2 focus:ring-indigo-400"
        />
        <button
          type="submit"
          className="rounded-xl bg-indigo-600 text-white px-5 py-3 text-sm font-medium hover:bg-indigo-700 active:scale-95 transition-transform"
        >
          Add
        </button>
      </form>

      {/* List */}
      <ul className="space-y-2 mb-6">
        {items.length === 0 && (
          <li className="text-center text-gray-400 text-sm py-8">No items. Add one above!</li>
        )}
        {items.map((item) => (
          <li key={item.id} className="flex items-center gap-3 rounded-xl bg-white shadow-sm border border-gray-100 px-4 py-3">
            <input
              type="checkbox"
              checked={!!item.done}
              onChange={() => toggle(item)}
              className="w-5 h-5 accent-indigo-600 shrink-0"
            />
            {editId === item.id ? (
              <input
                value={editText}
                onChange={(e) => setEditText(e.target.value)}
                onBlur={() => saveEdit(item.id)}
                onKeyDown={(e) => e.key === 'Enter' && saveEdit(item.id)}
                autoFocus
                className="flex-1 border-b border-indigo-400 focus:outline-none text-sm py-0.5"
              />
            ) : (
              <span
                onDoubleClick={() => { setEditId(item.id); setEditText(item.text); }}
                className={`flex-1 text-sm ${item.done ? 'line-through text-gray-400' : ''}`}
              >
                {item.text}
              </span>
            )}
            <button
              onClick={() => deleteItem(item.id)}
              className="text-gray-300 hover:text-red-400 text-lg leading-none transition-colors"
              aria-label="delete"
            >
              ×
            </button>
          </li>
        ))}
      </ul>

      {/* Footer */}
      <div className="flex items-center justify-between text-xs text-gray-500">
        <span>{activeCount} item{activeCount !== 1 ? 's' : ''} left</span>
        <div className="flex gap-1">
          {(['all', 'active', 'completed'] as Filter[]).map((f) => (
            <button
              key={f}
              onClick={() => changeFilter(f)}
              className={`px-3 py-1 rounded-lg capitalize transition-colors ${filter === f ? 'bg-indigo-100 text-indigo-700 font-medium' : 'hover:bg-gray-100'}`}
            >
              {f}
            </button>
          ))}
        </div>
        {hasCompleted && (
          <button onClick={clearCompleted} className="hover:text-red-500 transition-colors">
            Clear completed
          </button>
        )}
      </div>

      {/* Gym FAB */}
      <button
        ref={fabRef}
        onClick={() => setGymOpen((v) => !v)}
        className="fixed bottom-6 left-4 w-12 h-12 rounded-full bg-indigo-600 text-white shadow-lg flex items-center justify-center text-lg hover:bg-indigo-700 active:scale-95 transition-transform z-40"
        title="Gym controls (↑)"
      >
        🏋️
      </button>

      {/* Gym panel */}
      {gymOpen && (
        <div className="fixed inset-x-4 bottom-24 bg-white rounded-2xl shadow-2xl border border-gray-200 p-5 z-50 max-h-[70vh] overflow-y-auto">
          <div className="flex justify-between items-center mb-4">
            <h2 className="font-semibold text-gray-800">Gym Controls</h2>
            <button onClick={() => setGymOpen(false)} className="text-gray-400 hover:text-gray-600 text-xl leading-none">×</button>
          </div>

          {prompt && (
            <div className="mb-4 rounded-xl bg-indigo-50 border border-indigo-200 px-4 py-3 text-sm text-indigo-800">
              <span className="font-medium">Task: </span>{prompt}
            </div>
          )}

          <div className="flex gap-2 mb-3">
            <select
              value={selectedTask}
              onChange={(e) => setSelectedTask(e.target.value)}
              className="flex-1 rounded-lg border border-gray-200 px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-indigo-400"
            >
              <option value="">Select task…</option>
              <optgroup label="Primitives">
                {tasks.filter((t) => t.type === 'primitive').map((t) => (
                  <option key={t.id} value={t.id}>{t.id}</option>
                ))}
              </optgroup>
              <optgroup label="Advanced">
                {tasks.filter((t) => t.type === 'advanced').map((t) => (
                  <option key={t.id} value={t.id}>{t.id}</option>
                ))}
              </optgroup>
            </select>
            <button onClick={startTask} className="rounded-lg bg-indigo-600 text-white px-4 py-2 text-sm font-medium hover:bg-indigo-700">
              Start
            </button>
          </div>

          {isRetrieval && (
            <input
              value={agentAnswer}
              onChange={(e) => setAgentAnswer(e.target.value)}
              placeholder="Your answer…"
              className="w-full rounded-lg border border-gray-200 px-3 py-2 text-sm mb-3 focus:outline-none focus:ring-2 focus:ring-indigo-400"
            />
          )}

          <div className="flex gap-2 mb-3">
            <button onClick={evaluate} className="flex-1 rounded-lg bg-green-600 text-white px-3 py-2 text-sm font-medium hover:bg-green-700">
              Evaluate
            </button>
            <button onClick={reset} className="rounded-lg bg-gray-200 text-gray-700 px-3 py-2 text-sm font-medium hover:bg-gray-300">
              Reset
            </button>
          </div>

          {evalResult && (
            <div className={`rounded-xl px-4 py-3 text-sm ${evalResult.success ? 'bg-green-50 border border-green-200 text-green-800' : 'bg-red-50 border border-red-200 text-red-800'}`}>
              <div className="font-medium mb-1">{evalResult.success ? '✓ Passed' : '✗ Failed'} — reward: {(evalResult.reward ?? 0).toFixed(2)}</div>
              <div>{evalResult.message}</div>
              {evalResult.subResults?.length > 1 && (
                <ul className="mt-2 space-y-1">
                  {evalResult.subResults.map((s: any, i: number) => (
                    <li key={i} className="text-xs">{s.success ? '✓' : '✗'} {s.message}</li>
                  ))}
                </ul>
              )}
            </div>
          )}
        </div>
      )}
    </div>
  );
}

