const EVAL_SERVER = process.env.EVAL_SERVER;

export function forwardEvent(event: string, payload: object) {
  if (!EVAL_SERVER) return;
  const url = `${EVAL_SERVER.replace(/\/$/, '')}/${event}`;
  fetch(url, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ ...payload, timestamp: new Date().toISOString() }),
  }).catch(() => {});
}

import Database from 'better-sqlite3';
import fs from 'fs';
import path from 'path';

const DB_DIR = path.join(process.cwd(), '.data');
fs.mkdirSync(DB_DIR, { recursive: true });

const dbs = new Map<string, Database.Database>();

function dbPath(sessionId: string) {
  return path.join(DB_DIR, `${sessionId}.db`);
}

export function getDb(sessionId = 'default'): Database.Database {
  if (!dbs.has(sessionId)) {
    const db = new Database(dbPath(sessionId));
    db.pragma('journal_mode = WAL');
    const schema = fs.readFileSync(path.join(process.cwd(), 'schema.sql'), 'utf8');
    db.exec(schema);
    dbs.set(sessionId, db);
  }
  return dbs.get(sessionId)!;
}

export function createSession(): string {
  const id = Math.random().toString(36).slice(2, 10);
  getDb(id);
  return id;
}

export function destroySession(sessionId: string) {
  const db = dbs.get(sessionId);
  if (db) {
    db.close();
    dbs.delete(sessionId);
    try { fs.unlinkSync(dbPath(sessionId)); } catch {}
  }
}

export function resetDb(sessionId = 'default') {
  const db = getDb(sessionId);
  const schema = fs.readFileSync(path.join(process.cwd(), 'schema.sql'), 'utf8');
  db.exec(schema);
  const seed = fs.readFileSync(path.join(process.cwd(), 'tasks/_shared/seed.sql'), 'utf8');
  db.exec(seed);
  gymStates.delete(sessionId);
}

// ── gym state ────────────────────────────────────────────────────────────────

export interface GymTask {
  id: string;
  type: 'primitive' | 'advanced';
  prompt: string;
  steps: any[];
}

const gymStates = new Map<string, GymTask>();

export function loadAllTasks(): any[] {
  const tasks: any[] = [];
  for (const type of ['primitives', 'advanced']) {
    const dir = path.join(process.cwd(), 'tasks', type);
    if (!fs.existsSync(dir)) continue;
    for (const id of fs.readdirSync(dir)) {
      const taskFile = path.join(dir, id, 'task.json');
      if (fs.existsSync(taskFile)) {
        const t = JSON.parse(fs.readFileSync(taskFile, 'utf8'));
        t.type = type === 'primitives' ? 'primitive' : 'advanced';
        tasks.push(t);
      }
    }
  }
  return tasks;
}

export function startTask(
  sessionId: string,
  seedPath: string,
  task: any,
  extraSeedPath?: string
) {
  const db = getDb(sessionId);
  const schema = fs.readFileSync(path.join(process.cwd(), 'schema.sql'), 'utf8');
  db.exec(schema);
  db.exec(fs.readFileSync(path.join(process.cwd(), seedPath), 'utf8'));
  if (extraSeedPath) {
    db.exec(fs.readFileSync(path.join(process.cwd(), extraSeedPath), 'utf8'));
  }

  // Build flat step list for evaluate
  let steps: any[];
  if (task.type === 'primitive') {
    steps = [{ id: task.id, evalFunc: task.evalFunc, metadata: task.defaultParams ?? {}, weight: task.weight ?? 1 }];
    // Retrieval primitive: carry expected_value into metadata
    if (task.evalFunc === 'check_retrieval') {
      steps[0].metadata = { ...steps[0].metadata, expected_value: task.expected_value };
    }
  } else {
    const allTasks = loadAllTasks();
    const primMap = Object.fromEntries(allTasks.filter((t) => t.type === 'primitive').map((t) => [t.id, t]));
    steps = (task.steps as any[]).map((s, i) => {
      const [primId, overrides] = Array.isArray(s) ? s : [s, {}];
      const prim = primMap[primId];
      return {
        id: `${primId}_${i}`,
        evalFunc: prim?.evalFunc ?? primId,
        metadata: { ...(prim?.defaultParams ?? {}), ...overrides },
        weight: prim?.weight ?? 1,
        overrides,
      };
    });
  }

  gymStates.set(sessionId, {
    id: task.id,
    type: task.type,
    prompt: task.description,
    steps,
  });
}

export function getCurrentTask(sessionId = 'default'): GymTask | null {
  return gymStates.get(sessionId) ?? null;
}

import { NextRequest } from 'next/server';

export function getSessionId(request: NextRequest): string {
  return request.headers.get('x-session-id') ??
    request.cookies.get('gym_session')?.value ??
    'default';
}

